style.css:
@-moz-document domain("youtube.com") {
/* ==================== FUNDO FRUTIGER AERO ==================== */
  body {
    background: linear-gradient(
        135deg,
        rgba(155, 222, 255, 0.7) 0%,
        rgba(100, 200, 255, 0.5) 25%,
        rgba(70, 190, 240, 0.4) 50%,
        rgba(120, 230, 210, 0.6) 75%,
        rgba(160, 240, 200, 0.7) 100%
      ),
      url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200"><path fill="%2378c5ff" d="M55,35 Q70,20 85,35 T115,35 Q130,20 145,35 T175,35 L175,165 L55,165 Z"/></svg>') repeat,
      radial-gradient(circle at 10% 20%, #a8e6cf 0%, #dcedc1 20%, #ffd3b6 40%, #ffaaa5 60%, #ff8b94 80%);
    background-blend-mode: soft-light;
    background-attachment: fixed;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif !important;
    color: #003366 !important;
  }

  /* ==================== EFEITO DE ÁGUA ==================== */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><path fill="%2300aaff" opacity="0.1" d="M40,120 Q60,80 100,120 Q140,160 180,120 L180,200 L40,200 Z"/></svg>') repeat;
    pointer-events: none;
    z-index: -1;
    animation: waterEffect 15s infinite linear;
  }

  @keyframes waterEffect {
    0% { background-position: 0 0; }
    100% { background-position: 500px 500px; }
  }

  /* ==================== BARRA SUPERIOR ==================== */
  #masthead-container {
    background: linear-gradient(160deg, rgba(120, 220, 255, 0.8), rgba(180, 240, 255, 0.6)) !important;
    backdrop-filter: blur(12px) saturate(180%);
    border-bottom: 2px solid rgba(255, 255, 255, 0.7) !important;
    box-shadow: 0 4px 20px rgba(0, 100, 200, 0.3) !important;
    border-radius: 0 0 24px 24px !important;
  }

  /* ==================== BOTÕES PRINCIPAIS ==================== */
  ytd-button-renderer, .yt-spec-button-shape-next {
    background: linear-gradient(
      to bottom,
      rgba(100, 210, 255, 0.7),
      rgba(70, 180, 230, 0.5)
    ) !important;
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.6) !important;
    border-radius: 18px !important;
    box-shadow: 
      0 4px 8px rgba(0, 100, 180, 0.3),
      inset 0 2px 4px rgba(255, 255, 255, 0.5) !important;
    color: #004d80 !important;
    text-shadow: 0 1px 1px rgba(255, 255, 255, 0.8) !important;
    font-weight: 600 !important;
    padding: 8px 20px !important;
    margin: 0 5px !important;
    transition: all 0.3s ease !important;
  }

  ytd-button-renderer:hover, .yt-spec-button-shape-next:hover {
    background: linear-gradient(
      to bottom,
      rgba(120, 230, 255, 0.8),
      rgba(90, 200, 250, 0.6)
    ) !important;
    transform: translateY(-2px) scale(1.05);
    box-shadow: 
      0 6px 12px rgba(0, 120, 220, 0.4),
      inset 0 2px 6px rgba(255, 255, 255, 0.7) !important;
  }

  /* ==================== MENU LATERAL ==================== */
  #guide-content.ytd-app {
    background: rgba(170, 230, 255, 0.6) !important;
    backdrop-filter: blur(15px);
    border-right: 2px solid rgba(255, 255, 255, 0.5) !important;
    border-radius: 0 24px 24px 0 !important;
    margin-top: 20px;
    padding: 15px 5px !important;
  }

  #guide-wrapper {
    background: transparent !important;
  }

  ytd-guide-section-renderer {
    background: rgba(200, 240, 255, 0.5) !important;
    backdrop-filter: blur(5px);
    border-radius: 18px !important;
    margin: 12px 8px !important;
    padding: 10px 0 !important;
    border: 1px solid rgba(255, 255, 255, 0.4) !important;
    box-shadow: 0 4px 12px rgba(0, 100, 180, 0.2) !important;
  }

  /* ==================== VÍDEOS ==================== */
  ytd-rich-item-renderer, ytd-video-renderer {
    background: rgba(200, 240, 255, 0.7) !important;
    backdrop-filter: blur(10px);
    border-radius: 24px !important;
    border: 1px solid rgba(255, 255, 255, 0.6) !important;
    overflow: hidden;
    box-shadow: 
      0 8px 16px rgba(0, 100, 180, 0.2),
      inset 0 0 12px rgba(255, 255, 255, 0.6) !important;
    margin: 12px !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
  }

  ytd-rich-item-renderer:hover, ytd-video-renderer:hover {
    transform: translateY(-6px) scale(1.02);
    box-shadow: 
      0 12px 24px rgba(0, 150, 240, 0.3),
      inset 0 0 20px rgba(255, 255, 255, 0.8) !important;
  }

  /* ==================== PLAYER ==================== */
  .html5-video-player {
    background: linear-gradient(
      135deg,
      rgba(140, 220, 255, 0.7),
      rgba(180, 240, 255, 0.5)
    ) !important;
    backdrop-filter: blur(10px);
    border-radius: 24px !important;
    border: 2px solid rgba(255, 255, 255, 0.7) !important;
    overflow: hidden;
    box-shadow: 
      0 8px 32px rgba(0, 100, 200, 0.4),
      inset 0 0 20px rgba(255, 255, 255, 0.6) !important;
    padding: 15px !important;
  }

  /* ==================== BARRA DE PROGRESSO ==================== */
  .ytp-play-progress {
    background: linear-gradient(
      to right,
      #00ccff,
      #00ffaa
    ) !important;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.7) !important;
    height: 6px !important;
  }

  .ytp-scrubber-container {
    background: white !important;
    border: 2px solid #00ccff !important;
    box-shadow: 0 0 12px rgba(0, 200, 255, 0.8) !important;
  }

  /* ==================== COMENTÁRIOS ==================== */
  ytd-comment-thread-renderer {
    background: rgba(180, 235, 255, 0.6) !important;
    backdrop-filter: blur(8px);
    border-radius: 18px !important;
    margin: 15px 0 !important;
    padding: 15px !important;
    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    box-shadow: 0 4px 12px rgba(0, 100, 180, 0.15) !important;
  }

  /* ==================== ELEMENTOS DE FORMULÁRIO ==================== */
  input, textarea, select {
    background: rgba(200, 240, 255, 0.7) !important;
    backdrop-filter: blur(5px);
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    border-radius: 16px !important;
    padding: 12px 18px !important;
    box-shadow: 
      inset 0 2px 6px rgba(0, 80, 150, 0.2),
      0 4px 8px rgba(0, 150, 255, 0.1) !important;
    color: #003366 !important;
    font-size: 16px !important;
  }

  input:focus, textarea:focus {
    background: rgba(220, 250, 255, 0.9) !important;
    box-shadow: 
      inset 0 2px 8px rgba(0, 100, 180, 0.3),
      0 0 15px rgba(0, 200, 255, 0.5) !important;
    outline: none;
  }

  /* ==================== ANIMAÇÕES ADICIONAIS ==================== */
  @keyframes float {
    0% { transform: translateY(0px); }
    50% { transform: translateY(-10px); }
    100% { transform: translateY(0px); }
  }

  .cloud-effect {
    position: fixed;
    width: 200px;
    height: 60px;
    background: rgba(255, 255, 255, 0.9);
    border-radius: 50%;
    filter: blur(15px);
    z-index: -1;
    animation: float 15s infinite ease-in-out;
    opacity: 0.7;
  }

  #cloud1 {
    top: 15%;
    left: 5%;
    width: 150px;
    height: 50px;
    animation-duration: 18s;
  }

  #cloud2 {
    top: 25%;
    right: 10%;
    width: 180px;
    height: 55px;
    animation-duration: 22s;
    animation-delay: 3s;
  }

  #cloud3 {
    bottom: 30%;
    left: 15%;
    width: 120px;
    height: 40px;
    animation-duration: 16s;
    animation-delay: 5s;
  }

  /* ==================== FOOTER ==================== */
  ytd-app::after {
    content: "";
    display: block;
    height: 100px;
    background: linear-gradient(
      to top,
      rgba(70, 160, 220, 0.7),
      transparent
    );
    border-top: 2px solid rgba(255, 255, 255, 0.6);
    margin-top: 30px;
    backdrop-filter: blur(5px);
    border-radius: 24px 24px 0 0;
  }

  /* ==================== SCROLLBAR ==================== */
  ::-webkit-scrollbar {
    width: 14px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(180, 230, 255, 0.3);
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      to bottom,
      rgba(100, 200, 255, 0.8),
      rgba(70, 180, 230, 0.6)
    );
    border-radius: 10px;
    border: 2px solid rgba(255, 255, 255, 0.5);
  }

  /* ==================== ÍCONES ==================== */
  .yt-icon {
    filter: drop-shadow(0 2px 3px rgba(0, 100, 180, 0.3)) !important;
    transition: all 0.3s ease !important;
  }

  .yt-icon:hover {
    filter: drop-shadow(0 0 8px rgba(0, 200, 255, 0.7)) !important;
    transform: scale(1.2);
  }

  /* ==================== TIPOGRAFIA ==================== */
  h1, h2, h3, h4, .title, .yt-formatted-string {
    color: #004d80 !important;
    text-shadow: 
      0 1px 0 rgba(255, 255, 255, 0.7),
      0 2px 4px rgba(0, 150, 255, 0.3) !important;
    font-weight: 600 !important;
    letter-spacing: 0.3px !important;
  }

  a {
    color: #0088cc !important;
    text-shadow: 0 1px 1px rgba(255, 255, 255, 0.8) !important;
    transition: all 0.3s ease !important;
  }

  a:hover {
    color: #00ccff !important;
    text-shadow: 0 0 8px rgba(0, 200, 255, 0.7) !important;
  }

  /* ==================== RESPONSIVIDADE ==================== */
  @media (max-width: 1200px) {
    ytd-rich-item-renderer, ytd-video-renderer {
      max-width: 95% !important;
      margin: 12px auto !important;
    }
  }
}
